package com.elektoryk.scan.ui;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import com.elektoryk.scan.model.*;import com.elektoryk.scan.storage.ObjectFlowRepository;import java.text.DateFormat;import java.util.*;
public class CrewActivity extends Activity{
 private String projectId;private ObjectFlowRepository repo;private ObjectFlowState state;private NumberStepper rate,expense;private ChoiceStrip expenseType;private EditText worker,note;
 @Override protected void onCreate(Bundle b){super.onCreate(b);projectId=getIntent().getStringExtra("projectId");repo=new ObjectFlowRepository(this);build();}
 private void build(){state=repo.load(projectId);ScrollView s=new ScrollView(this);s.setBackgroundColor(Ui.BG);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,30));s.addView(root);root.addView(Ui.brandHeader(this,"ELEKTORYK • Команда і витрати","Години підсобника, ставка та витрати по об'єкту.","CREW",true));
   WorkerShift open=openShift();LinearLayout shift=Ui.card(this);shift.addView(Ui.title(this,open==null?"Почати зміну":"Зміна триває",18));worker=new EditText(this);worker.setHint("Підсобник / майстер");worker.setText(open==null?"Підсобник":open.workerName);worker.setTextColor(Ui.TEXT);worker.setHintTextColor(Ui.MUTED);shift.addView(worker);rate=new NumberStepper(this,"грн/год");rate.configure(0,5000,10,0);rate.setValue(open==null?0:open.hourlyRate);shift.addView(rate);Button toggle=Ui.button(this,open==null?"▶ Підсобник приступив":"■ Підсобник закінчив");toggle.setOnClickListener(v->{if(openShift()==null){WorkerShift x=new WorkerShift();x.workerName=worker.getText().toString().trim();if(x.workerName.isEmpty())x.workerName="Підсобник";x.hourlyRate=rate.getValue();x.startedAt=System.currentTimeMillis();state.shifts.add(x);}else openShift().endedAt=System.currentTimeMillis();repo.save(state);build();});shift.addView(toggle,Ui.lpMatchWrap(this,8));root.addView(shift,Ui.lpMatchWrap(this,10));
   LinearLayout ex=Ui.card(this);ex.addView(Ui.title(this,"Додати витрату",18));expenseType=new ChoiceStrip(this);expenseType.setItems(new String[]{"FOOD","TRAVEL","TOOLS","MATERIAL_EXTRA","OTHER"},new String[]{"Харчування","Дорога","Інструмент","Дод. матеріал","Інше"},"FOOD");ex.addView(expenseType);expense=new NumberStepper(this,"грн");expense.configure(0,1000000,10,0);ex.addView(expense);note=new EditText(this);note.setHint("Примітка");note.setTextColor(Ui.TEXT);note.setHintTextColor(Ui.MUTED);ex.addView(note);Button add=Ui.secondaryButton(this,"+ Додати витрату");add.setOnClickListener(v->{ProjectExpense x=new ProjectExpense();try{x.category=ProjectExpense.Category.valueOf(expenseType.getSelectedKey());}catch(Exception ignored){}x.amount=expense.getValue();x.note=note.getText().toString().trim();state.expenses.add(x);repo.save(state);build();});ex.addView(add,Ui.lpMatchWrap(this,7));root.addView(ex,Ui.lpMatchWrap(this,10));
   double hours=0,pay=0,cost=0;long now=System.currentTimeMillis();for(WorkerShift x:state.shifts){hours+=x.hours(now);pay+=x.pay(now);}for(ProjectExpense x:state.expenses)cost+=x.amount;LinearLayout total=Ui.card(this);total.addView(Ui.title(this,String.format(Locale.US,"%.1f год • %.0f грн оплата",hours,pay),19));total.addView(Ui.muted(this,String.format(Locale.US,"Інші витрати: %.0f грн • Разом по команді/витратах: %.0f грн",cost,pay+cost)));root.addView(total,Ui.lpMatchWrap(this,10));
   DateFormat df=DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT);for(WorkerShift x:state.shifts){LinearLayout c=Ui.softCard(this);c.addView(Ui.title(this,x.workerName,16));c.addView(Ui.muted(this,df.format(new Date(x.startedAt))+" → "+(x.endedAt>0?df.format(new Date(x.endedAt)):"зараз")+String.format(Locale.US," • %.2f год • %.0f грн",x.hours(now),x.pay(now))));root.addView(c,Ui.lpMatchWrap(this,6));}for(ProjectExpense x:state.expenses){LinearLayout c=Ui.softCard(this);c.addView(Ui.title(this,x.category.name()+" • "+Math.round(x.amount)+" грн",15));if(!x.note.isEmpty())c.addView(Ui.muted(this,x.note));root.addView(c,Ui.lpMatchWrap(this,5));}setContentView(s);}
 private WorkerShift openShift(){for(int i=state.shifts.size()-1;i>=0;i--)if(state.shifts.get(i).isOpen())return state.shifts.get(i);return null;}
}
